local function run(action)
    -- Only constants from the allowlist reach the shell, never web input.
    local allowed = {
        get_stats = true, get_peers = true, screen_wake = true, screen_sleep = true,
        capture_screen = true, reboot = true,
        reconnect_data = true, data_on = true, data_off = true,
        start_vpn = true, stop_vpn = true,
        uplink_link = true, uplink_fallback = true, uplink_primary = true, uplink_stop = true,
    }
    if not allowed[action] then return nil, "Unsupported smartphone action" end
    local deadline = action == "capture_screen" and "22" or "18"
    if action:match("^uplink_") then deadline = "40" end
    local command = " /usr/bin/phone_stats.sh " .. action .. " 2>/dev/null"
    local pipe = io.popen("if timeout --help 2>&1 | grep -q -- '-t SECS'; then timeout -t " .. deadline .. command ..
        "; else timeout " .. deadline .. command .. "; fi; printf '\\nEXIT_STATUS|%s\\n' \"$?\"")
    if not pipe then return nil, "Unable to start smartphone helper" end
    local output = pipe:read("*a")
    pipe:close()
    local body, status = output:match("^(.*)\nEXIT_STATUS|(%d+)%s*$")
    if status ~= "0" then
        -- Keep USB identity and the specific ADB state in error stats, too.
        if action == "get_stats" and body and body:match("^ERROR|") then return body end
        if action == "get_stats" then
            -- The outer deadline can expire before the helper prints its final
            -- payload. Preserve USB identity without making another ADB call.
            local diagnostics = io.popen("if timeout --help 2>&1 | grep -q -- '-t SECS'; then timeout -t 3 /usr/bin/phone_stats.sh get_usb_info; else timeout 3 /usr/bin/phone_stats.sh get_usb_info; fi 2>/dev/null")
            local usb = diagnostics and diagnostics:read("*a") or ""
            if diagnostics then diagnostics:close() end
            local timed_out = status == "124" or status == "137" or status == "143"
            return "ERROR|" .. (timed_out and "Phone telemetry timed out. USB detection is independent of ADB." or "Unable to read phone telemetry. Check the Smartphone backend.") ..
                "\nERROR_CODE|" .. (timed_out and "telemetry_timeout" or "helper_error") .. "\n" .. usb
        end
        return nil, (body and body:match("ERROR|([^\r\n]+)")) or "Smartphone request failed or timed out"
    end
    return body
end

register {
    objectType = {
        name = "rpc.smartphone.", access = "readOnly", minEntries = 1, maxEntries = 1,
        parameters = {
            stats = { access = "readOnly", type = "string" },
            peers = { access = "readOnly", type = "string" },
            action = { access = "readWrite", type = "string" },
        },
    },
    get = {
        stats = function()
            local result, err = run("get_stats")
            return result or ("ERROR|" .. err)
        end,
        peers = function()
            local result, err = run("get_peers")
            return result or ("ERROR|" .. err)
        end,
        action = function() return "" end,
    },
    set = {
        action = function(_, _, value)
            if value == "get_stats" or value == "get_peers" then return nil, "Use the read-only parameter" end
            local result, err = run(value)
            if not result then return nil, err end
            return true
        end,
    },
}
